<?php
namespace App\Filament\Resources\Materials;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Materials\Pages\ManageMaterials; use App\Models\Material;
use BackedEnum; use Filament\Actions\BulkActionGroup; use Filament\Actions\DeleteAction; use Filament\Actions\DeleteBulkAction; use Filament\Actions\EditAction; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table;
class MaterialResource extends AdminResource { protected static ?string $model = Material::class; protected static string $viewPermission = 'catalog.view'; protected static ?string $managePermission = 'catalog.update'; protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedCube; protected static ?string $navigationLabel = 'Chất liệu'; protected static string|\UnitEnum|null $navigationGroup = 'Sản phẩm'; protected static ?int $navigationSort = 40;
 public static function form(Schema $s): Schema { return $s->components([TextInput::make('name')->label('Tên')->required(), Select::make('material_type')->label('Loại')->options(['metal'=>'Kim loại','gemstone'=>'Đá','leather'=>'Da','ceramic'=>'Gốm','other'=>'Khác'])->required()]); } public static function table(Table $t): Table { return $t->columns([TextColumn::make('name')->label('Tên')->searchable(),TextColumn::make('material_type')->label('Loại')->badge()])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]); } public static function getPages(): array { return ['index'=>ManageMaterials::route('/')]; } }
